vulnerable_code:
function addBalance(uint256 amount) public {
    balance += amount;
}

fixed_code:
function addBalance(uint256 amount) public {
    uint256 newBalance = balance + amount;
    require(newBalance >= balance, "Overflow");
    balance = newBalance;
}

vulnerable_code:
// Variant 9496: staking
function upgrade(address newImplementation) public {
    implementation = newImplementation;
}

fixed_code:
function upgrade(address newImplementation) public onlyOwner {
    require(newImplementation != address(0), "Zero address");
    require(Address.isContract(newImplementation), "Not a contract");
    implementation = newImplementation;
}

vulnerable_code:
// Variant 5560: options
function destroy() public {
    selfdestruct(payable(msg.sender));
}

fixed_code:
function destroy() public onlyOwner {
    emit ContractDestroyed(address(this));
    selfdestruct(payable(owner));
}

vulnerable_code:
function transferOwnership(address newOwner) public {
    require(tx.origin == owner, "Not owner");
    owner = newOwner;
}

fixed_code:
function transferOwnership(address newOwner) public onlyOwner {
    require(newOwner != address(0), "Zero address");
    emit OwnershipTransferred(owner, newOwner);
    owner = newOwner;
}

vulnerable_code:
function getCollateralValue() public view returns (uint256) {
    return balanceOfPool * getPrice();
}

fixed_code:
// Variant 7098: lending
function getCollateralValue() public view returns (uint256) {
    (uint256 reserve0, uint256 reserve1, ) = pool.getReserves();
    uint256 twapPrice = TWAP.getPrice(reserve0, reserve1);
    return Math.min(balanceOfPool, reserve0) * twapPrice / 1e18;
}

vulnerable_code:
function getPrice() public view returns (uint256) {
    return spotPrice;
}

fixed_code:
function getPrice() public view returns (uint256) {
    (uint256 reserve0, uint256 reserve1, ) = pool.getReserves();
    return reserve0 * 1e18 / reserve1;
}

