fixed_code:
// Variant 4626: bridge
function permit(address owner, address spender, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public {
    require(block.timestamp <= deadline, "Expired");
    bytes32 hash = keccak256(abi.encodePacked(owner, spender, amount, nonces[owner]++, deadline));
    require(ecrecover(hash, v, r, s) == owner, "Invalid sig");
    _approve(owner, spender, amount);
}

